		case_r.zRot += Mth.sin(state.ageInTicks * 0.3F + 3.141592653589793F) * (0.05F + 0.0F * state.walkAnimationSpeed);
		head.yRot += state.yRot * 0.017453292F * 0.6F;
		head.xRot += state.xRot * 0.017453292F * 0.6F;
		ant_l0.xRot += Mth.sin(state.ageInTicks * 0.18F + 0.0F) * (0.14F + 0.0F * state.walkAnimationSpeed);
		ant_l1.xRot += Mth.sin(state.ageInTicks * 0.18F + 1.0F) * (0.14F + 0.0F * state.walkAnimationSpeed);
		leg_l0.yRot += Mth.cos(state.walkAnimationPos * 0.6662F + 0.0F) * 0.7F * state.walkAnimationSpeed;
		leg_l0.zRot += Mth.cos(state.walkAnimationPos * 0.6662F + 1.57F) * 0.4F * state.walkAnimationSpeed;
		leg_l1.yRot += Mth.cos(state.walkAnimationPos * 0.6662F + 3.141592653589793F) * 0.7F * state.walkAnimationSpeed;
		leg_l1.zRot += Mth.cos(state.walkAnimationPos * 0.6662F + 4.711592653589793F) * 0.4F * state.walkAnimationSpeed;
		leg_l2.yRot += Mth.cos(state.walkAnimationPos * 0.6662F + 0.0F) * 0.7F * state.walkAnimationSpeed;
		leg_l2.zRot += Mth.cos(state.walkAnimationPos * 0.6662F + 1.57F) * 0.4F * state.walkAnimationSpeed;
		ant_r0.xRot += Mth.sin(state.ageInTicks * 0.18F + 1.7F) * (0.14F + 0.0F * state.walkAnimationSpeed);
		ant_r1.xRot += Mth.sin(state.ageInTicks * 0.18F + 2.7F) * (0.14F + 0.0F * state.walkAnimationSpeed);
		leg_r0.yRot += Mth.cos(state.walkAnimationPos * 0.6662F + 3.141592653589793F) * 0.7F * state.walkAnimationSpeed;
